#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/sys/atomic.h>

#define P4WQ_MAX_ITEMS_TEST CONFIG_P4WQ_MAX_ITEMS

/* Define a workqueue for testing */
K_P4WQ_DEFINE(p4wq, P4WQ_MAX_ITEMS_TEST);

/* Global variables for tracking work execution */
static atomic_t work_count;
static K_SEM_DEFINE(work_sem, 0, P4WQ_MAX_ITEMS_TEST);

/* Work handler function */
static void work_handler(struct k_p4wq_work *work)
{
    atomic_inc(&work_count);
    k_sem_give(&work_sem);
}

/* Helper to submit a work item and check success */
static bool add_new_item(struct k_p4wq_work *work)
{
    return k_p4wq_submit(&p4wq, work) == 0;
}

/* Helper to remove all items from the queue and wait for them to complete */
static void drain_queue(void)
{
    while (k_p4wq_item_count(&p4wq) > 0) {
        k_sem_take(&work_sem, K_FOREVER);
    }
    atomic_set(&work_count, 0);
}

/* Test cases */

/* Test submitting a single work item */
static void test_submit_single(void)
{
    struct k_p4wq_work work;
    k_p4wq_work_init(&work, work_handler);

    atomic_set(&work_count, 0);
    drain_queue(); /* Ensure queue is empty */
    zassert_true(add_new_item(&work), "Failed to submit single work item");
    k_sem_take(&work_sem, K_FOREVER);
    zassert_equal(atomic_get(&work_count), 1, "Work handler not executed");
    zassert_equal(k_p4wq_item_count(&p4wq), 0, "Queue not empty after single item");
}

/* Test filling the queue to its capacity */
static void test_fill_queue(void)
{
    /* Use an array of work items to avoid -EALREADY when submitting the same item */
    struct k_p4wq_work work_items[P4WQ_MAX_ITEMS_TEST];

    atomic_set(&work_count, 0);
    drain_queue(); /* Ensure queue is empty before filling */

    for (int i = 0; i < P4WQ_MAX_ITEMS_TEST; i++) {
        k_p4wq_work_init(&work_items[i], work_handler);
        zassert_true(add_new_item(&work_items[i]), "Failed to add work item %d", i);
    }

    zassert_equal(k_p4wq_item_count(&p4wq), P4WQ_MAX_ITEMS_TEST, "Queue not full");

    /* Test that adding one more item fails */
    struct k_p4wq_work extra_work;
    k_p4wq_work_init(&extra_work, work_handler);
    zassert_false(add_new_item(&extra_work), "Should not be able to add more items than capacity");

    /* Drain the queue for subsequent tests */
    drain_queue();
    zassert_equal(atomic_get(&work_count), P4WQ_MAX_ITEMS_TEST, "Not all work items executed");
    zassert_equal(k_p4wq_item_count(&p4wq), 0, "Queue not empty after draining");
}

/* Test submitting items with different priorities (basic check) */
static void test_submit_priorities(void)
{
    struct k_p4wq_work work_p0, work_p1;
    atomic_set(&work_count, 0);
    drain_queue();

    k_p4wq_work_init(&work_p0, work_handler);
    k_p4wq_work_init(&work_p1, work_handler);

    /* Submit lower priority first, then higher priority */
    k_p4wq_submit_prio(&p4wq, &work_p0, 1); /* Lower priority */
    k_p4wq_submit_prio(&p4wq, &work_p1, 0); /* Higher priority */

    /* Expect higher priority to run first, but we only check total count here */
    k_sem_take(&work_sem, K_FOREVER);
    k_sem_take(&work_sem, K_FOREVER);

    zassert_equal(atomic_get(&work_count), 2, "Both work items should have executed");
    zassert_equal(k_p4wq_item_count(&p4wq), 0, "Queue not empty after priority test");
}

/* Test cancelling a work item */
static void test_cancel_work(void)
{
    struct k_p4wq_work work;
    k_p4wq_work_init(&work, work_handler);

    atomic_set(&work_count, 0);
    drain_queue();

    zassert_true(add_new_item(&work), "Failed to submit work item for cancellation");
    zassert_equal(k_p4wq_item_count(&p4wq), 1, "Queue should have one item");

    /* Cancel the work item before it runs */
    zassert_true(k_p4wq_cancel(&p4wq, &work), "Failed to cancel work item");
    zassert_equal(k_p4wq_item_count(&p4wq), 0, "Queue should be empty after cancellation");

    /* Ensure handler was not called */
    k_sleep(K_MSEC(10)); /* Give some time for potential execution */
    zassert_equal(atomic_get(&work_count), 0, "Cancelled work item handler should not execute");

    /* Test cancelling a non-queued item */
    zassert_false(k_p4wq_cancel(&p4wq, &work), "Should not be able to cancel a non-queued item");
}


ZTEST_SUITE(lib_p4wq, NULL, NULL, NULL, NULL, NULL);

ZTEST_USER(lib_p4wq, test_submit_single);
ZTEST_USER(lib_p4wq, test_fill_queue);
ZTEST_USER(lib_p4wq, test_submit_priorities);
ZTEST_USER(lib_p4wq, test_cancel_work);
